// --- AUTO FIX FOR HINDI MANGAL MATRA RENDERING ---
(function() {
  function getGraphemes(str) {
    if (typeof Intl !== 'undefined' && Intl.Segmenter) {
      const segmenter = new Intl.Segmenter('hi', { granularity: 'grapheme' });
      return Array.from(segmenter.segment(str), s => s.segment);
    }
    return str.match(/[\u0900-\u097F][\u093E-\u094D\u0951-\u0954\u0962-\u0963]*|[^\u0900-\u097F]/g) || str.split('');
  }

  window.renderPromptDisplay = function(typedText) {
    const box = document.getElementById('storyPromptBox') || document.querySelector('.story-prompt-box');
    if (!box) return;

    if (typeof displayedPassage !== 'undefined' && typeof baseExerciseText !== 'undefined' && typeof testActive !== 'undefined') {
      if (displayedPassage.length - typedText.length < 100 && testActive) {
        displayedPassage += "\n\n" + baseExerciseText;
      }
    }

    const currentPassage = typeof displayedPassage !== 'undefined' ? displayedPassage : (box.innerText || '');
    const passageUnits = getGraphemes(currentPassage);
    const typedUnits = getGraphemes(typedText || '');

    const fragment = document.createDocumentFragment();

    for (let i = 0; i < passageUnits.length; i++) {
      const span = document.createElement('span');
      span.className = 'char';
      span.textContent = passageUnits[i];

      if (i < typedUnits.length) {
        if (typedUnits[i] === passageUnits[i]) {
          span.classList.add('correct');
        } else {
          span.classList.add('incorrect');
        }
      } else if (i === typedUnits.length) {
        span.classList.add('active');
      }

      fragment.appendChild(span);
    }

    box.innerHTML = '';
    box.appendChild(fragment);

    const activeChar = box.querySelector('.char.active');
    if (activeChar) {
      const offsetTop = activeChar.offsetTop;
      if (offsetTop > box.clientHeight - 40) {
        box.scrollTop = offsetTop - 35;
      }
    }
  };
})();
